programa
{
    funcao inteiro maior(inteiro a, inteiro b, inteiro c)
    {
        se (a >= b e a >= c)
        {
            retorne a
        }
        senao se (b >= a e b >= c)
        {
            retorne b
        }
        senao se (c >= a e c >= b)
        {
            retorne c
        }
    }

    funcao inicio()
    {
        inteiro a, b, c
        escreva("Digite tres numeros inteiros: ")
        leia(a)
        leia(b)
        leia(c)
        escreva("Maior = ", maior(a, b, c), "\n")
    }
}
